#!/usr/bin/env node
/**
 * gas-localnet.mjs — Real on-chain gas per Veil entry point, measured on a local Sui network.
 *
 * Every number this script prints is read from the `effects.gasUsed` of a transaction that was
 * actually executed by a local validator (`sui start`), carrying real Groth16 proofs generated by
 * snarkjs against the compiled circuits. Nothing is estimated.
 *
 * Flow (one run = one fresh publish of the package at --contracts):
 *   publish → faucet → create_pool → propose_withdraw_vk → 6 deposits → create_compliance_config
 *   → update_commitment_root → [wait one pool epoch] → 2× shielded_transfer → 2× zk_withdraw
 *   → 2× compliant_transfer → propose_vk_update(VK') → [wait one pool epoch]
 *   → shielded_transfer with a proof under the OLD VK (must abort E_INVALID_PROOF = 3)
 *   → shielded_transfer with a proof under VK' (must succeed) → freeze_pool → unfreeze_pool
 *   → zk_withdraw replay of a proof bound to recipient A, submitted with recipient B (probe for
 *     threat-model E7; reported, not asserted).
 *
 * Usage:
 *   sui start --with-faucet --force-regenesis &            # localnet: RPC :9000, faucet :9123
 *   node scripts/bench/gas-localnet.mjs --contracts contracts --label after [--json out.json]
 *
 * Prerequisites:
 *   - `sui` on PATH (used for `sui move build --dump-bytecode-as-base64 --build-env testnet`;
 *     framework addresses 0x1/0x2 are identical on localnet). Measured 2026-11-19 with
 *     `sui 1.72.1-94ad8ccd0ed6`, built from source at the exact rev pinned in contracts/Move.toml:
 *       cargo +1.92 build -p sui --bin sui   (CARGO_PROFILE_DEV_OPT_LEVEL=1, DEBUG=0)
 *     Gas is deterministic per protocol version — build profile does not affect it.
 *   - circuits/build{,-withdraw,-compliance}/ artifacts (see prove-latency.mjs header), plus
 *     circuits/build/transfer_alt_final.zkey + transfer_alt_vk.json: a second, independent
 *     contribution on transfer_0000.zkey, used as the rotated VK:
 *       npx snarkjs zkey contribute build/transfer_0000.zkey build/transfer_alt_final.zkey -e=alt
 *       npx snarkjs zkey export verificationkey build/transfer_alt_final.zkey build/transfer_alt_vk.json
 *   - --sui-framework <dir> (optional): rewrite the Sui dependency to a local checkout of the
 *     framework at the same git rev as Move.toml, so the build does not need a network fetch.
 */
import { execFileSync } from "child_process";
import { cpSync, mkdtempSync, readFileSync, writeFileSync, rmSync } from "fs";
import { tmpdir } from "os";
import { dirname, join, resolve } from "path";
import { fileURLToPath } from "url";
import { randomBytes } from "crypto";

import { Ed25519Keypair } from "@mysten/sui/keypairs/ed25519";
import { Transaction } from "@mysten/sui/transactions";
import { SuiJsonRpcClient } from "@mysten/sui/jsonRpc";
import { requestSuiFromFaucetV2 } from "@mysten/sui/faucet";
import { buildPoseidon } from "circomlibjs";
import * as snarkjs from "snarkjs";

import { proofToSuiBytes, publicInputsToSuiBytes, vkToSuiBytes } from "../src/proof-converter.ts";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, "..", "..");
const CIRCUITS = join(ROOT, "circuits");

const arg = (name, dflt) => {
  const i = process.argv.indexOf(`--${name}`);
  return i !== -1 ? process.argv[i + 1] : dflt;
};
const CONTRACTS = resolve(arg("contracts", join(ROOT, "contracts")));
const LABEL = arg("label", "run");
const JSON_OUT = arg("json", null);
const RPC = arg("rpc", "http://127.0.0.1:9000");
const FAUCET = arg("faucet", "http://127.0.0.1:9123");
const SUI_FRAMEWORK = arg("sui-framework", null);

const EPOCH_MS = 60_000; // pool minimum; keeps the timelock waits ~1 minute
const THRESHOLD = 1_000_000_000n;
const DENOM_SMALL = 100_000_000n;
const GAS_BUDGET = 2_000_000_000;
const DEPTH = 20;
const D = { COMMIT: 1n, NULL: 2n, TXAMT: 3n, CREDLEAF: 4n, CNULL: 5n, CTX: 6n, WNULL: 7n, RECIP: 8n };

const client = new SuiJsonRpcClient({ url: RPC, network: "localnet" });
const kp = Ed25519Keypair.generate();
const me = kp.toSuiAddress();
const rows = [];
let RGP = 1000n;

let poseidon, F;
const H = (xs) => F.toObject(poseidon(xs));

// ---------------------------------------------------------------------------
// Sparse Poseidon Merkle tree (empty sibling = 0 at every level, as in the circuit tests)
// ---------------------------------------------------------------------------
function buildTree(leaves) {
  const levels = [leaves.slice()];
  for (let d = 0; d < DEPTH; d++) {
    const prev = levels[d];
    const next = [];
    for (let i = 0; i < Math.max(1, Math.ceil(prev.length / 2)); i++) {
      next.push(H([prev[2 * i] ?? 0n, prev[2 * i + 1] ?? 0n]));
    }
    levels.push(next);
  }
  return {
    root: levels[DEPTH][0],
    path(index) {
      const el = [], ix = [];
      let i = index;
      for (let d = 0; d < DEPTH; d++) {
        el.push(levels[d][i ^ 1] ?? 0n);
        ix.push(BigInt(i & 1));
        i >>= 1;
      }
      return { pathElements: el, pathIndices: ix };
    },
  };
}

const le32 = (n) => {
  const b = new Uint8Array(32);
  let x = BigInt(n);
  for (let i = 0; i < 32; i++) { b[i] = Number(x & 0xffn); x >>= 8n; }
  return b;
};
const strs = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, Array.isArray(v) ? v.map(String) : String(v)]));

async function prove(circuit, dir, input, zkeyName = `${circuit}_final.zkey`) {
  const { proof, publicSignals } = await snarkjs.groth16.fullProve(
    strs(input),
    join(CIRCUITS, dir, `${circuit}_js`, `${circuit}.wasm`),
    join(CIRCUITS, dir, zkeyName),
  );
  return { proof: proofToSuiBytes(proof), inputs: publicInputsToSuiBytes(publicSignals) };
}
const vkBytes = (dir, name) => vkToSuiBytes(JSON.parse(readFileSync(join(CIRCUITS, dir, name), "utf-8")));

// ---------------------------------------------------------------------------
// Transaction execution + gas capture
// ---------------------------------------------------------------------------
async function exec(name, build, { expectAbort = null, record = true } = {}) {
  const tx = new Transaction();
  tx.setGasBudget(GAS_BUDGET);
  build(tx);
  const res = await client.signAndExecuteTransaction({
    transaction: tx, signer: kp,
    options: { showEffects: true, showObjectChanges: true, showEvents: true },
  });
  await client.waitForTransaction({ digest: res.digest });
  const st = res.effects.status;
  const g = res.effects.gasUsed;
  const row = {
    label: LABEL, op: name, status: st.status, error: st.error ?? null, digest: res.digest,
    computationCost: Number(g.computationCost), storageCost: Number(g.storageCost),
    storageRebate: Number(g.storageRebate), nonRefundableStorageFee: Number(g.nonRefundableStorageFee),
  };
  row.computationUnits = Number(BigInt(g.computationCost) / RGP);
  row.netMist = row.computationCost + row.storageCost - row.storageRebate;
  if (record) rows.push(row);
  console.log(
    `[${LABEL}] ${name.padEnd(34)} ${st.status.padEnd(7)} comp=${row.computationCost} (${row.computationUnits}u) ` +
    `stor=${row.storageCost} rebate=${row.storageRebate} net=${row.netMist}` + (st.error ? `  err=${st.error}` : ""),
  );
  if (expectAbort !== null) {
    if (st.status === "success") throw new Error(`${name}: expected abort ${expectAbort}, got success`);
    if (!new RegExp(`, ${expectAbort}\\)`).test(st.error ?? "")) throw new Error(`${name}: expected abort code ${expectAbort}, got ${st.error}`);
  } else if (st.status !== "success") {
    throw new Error(`${name} failed: ${st.error}`);
  }
  return res;
}
const created = (res, suffix) => res.objectChanges.find((c) => c.type === "created" && c.objectType.endsWith(suffix))?.objectId;

async function chainMs() {
  const o = await client.getObject({ id: "0x6", options: { showContent: true } });
  return Number(o.data.content.fields.timestamp_ms);
}
async function waitForEpoch(target) {
  for (;;) {
    const ms = await chainMs();
    const e = Math.floor(ms / EPOCH_MS);
    if (e >= target && ms % EPOCH_MS > 1500) return e;
    await new Promise((r) => setTimeout(r, 1000));
  }
}

// ---------------------------------------------------------------------------
async function main() {
  poseidon = await buildPoseidon();
  F = poseidon.F;
  RGP = BigInt(await client.getReferenceGasPrice());
  console.log(`=== Veil on-chain gas (${LABEL}) — contracts: ${CONTRACTS} — RGP ${RGP} MIST ===`);

  await requestSuiFromFaucetV2({ host: FAUCET, recipient: me });
  await requestSuiFromFaucetV2({ host: FAUCET, recipient: me });
  await new Promise((r) => setTimeout(r, 2000));

  // --- build + publish ---
  const work = mkdtempSync(join(tmpdir(), "veil-gas-"));
  cpSync(CONTRACTS, work, { recursive: true, filter: (p) => !p.includes("/build") });
  if (SUI_FRAMEWORK) {
    const toml = readFileSync(join(work, "Move.toml"), "utf-8").replace(/^Sui = .*$/m, `Sui = { local = "${SUI_FRAMEWORK}" }`);
    writeFileSync(join(work, "Move.toml"), toml);
    rmSync(join(work, "Move.lock"), { force: true });
  }
  const dump = JSON.parse(execFileSync("sui", ["move", "build", "--dump-bytecode-as-base64", "--build-env", "testnet", "--path", work], { encoding: "utf-8", stdio: ["ignore", "pipe", "inherit"] }));
  const pub = await exec("publish", (tx) => {
    const [cap] = tx.publish({ modules: dump.modules, dependencies: dump.dependencies });
    tx.transferObjects([cap], me);
  });
  const pkg = pub.objectChanges.find((c) => c.type === "published").packageId;
  const treasury = created(pub, "::coin::TreasuryCap<" + pub.objectChanges.find((c) => c.type === "published").packageId + "::token::TOKEN>");

  // --- proofs need the pool epoch, so set up the cryptographic material first ---
  const transferVk = vkBytes("build", "transfer_vk.json");
  const transferVkAlt = vkBytes("build", "transfer_alt_vk.json");
  const withdrawVk = vkBytes("build-withdraw", "withdraw_vk.json");
  const complianceVk = vkBytes("build-compliance", "compliance_vk.json");

  // Six users: T1, T2 (transfers), T3 (stale-VK probe), T4 (post-rotation), C1, C2 (compliant).
  const users = ["T1", "T2", "T3", "T4", "C1", "C2"].map((name, i) => ({
    name, secret: 1000n + BigInt(i), rOld: 0n, cumOld: 0n, rNew: 5000n + BigInt(i),
  }));
  for (const u of users) u.commitment = H([D.COMMIT, u.cumOld, u.rOld, u.secret]);
  // Two withdrawers — commitments are not part of the Merkle tree (withdraw.circom has no root).
  const withdrawers = ["W1", "W2"].map((name, i) => ({
    name, secret: 9000n + BigInt(i), rOld: 77n + BigInt(i), cumOld: 500n, rNew: 88n + BigInt(i), amount: 100n,
  }));
  for (const w of withdrawers) w.commitment = H([D.COMMIT, w.cumOld, w.rOld, w.secret]);

  const tree = buildTree(users.map((u) => u.commitment));
  const credLeaves = ["C1", "C2"].map((n) => {
    const u = users.find((x) => x.name === n);
    u.kyc = 2n; u.expiry = 1n << 40n; u.issuer = 42n;
    return H([D.CREDLEAF, u.secret, u.kyc, u.expiry, u.issuer]);
  });
  const credTree = buildTree(credLeaves);

  // --- admin setup ---
  await exec("token_faucet::faucet", (tx) => tx.moveCall({ target: `${pkg}::token_faucet::faucet`, arguments: [tx.object(treasury)] }));
  const cp = await exec("pool::create_pool", (tx) => tx.moveCall({
    target: `${pkg}::pool::create_pool`,
    arguments: [tx.pure.vector("u8", Array.from(transferVk)), tx.pure.u64(THRESHOLD), tx.pure.u64(EPOCH_MS)],
  }));
  const pool = created(cp, "::pool::Pool");
  const cap = created(cp, "::pool::AdminCap");
  await exec("pool::propose_withdraw_vk", (tx) => tx.moveCall({
    target: `${pkg}::pool::propose_withdraw_vk`,
    arguments: [tx.object(pool), tx.object(cap), tx.pure.vector("u8", Array.from(withdrawVk)), tx.object("0x6")],
  }));

  const coins = await client.getCoins({ owner: me, coinType: `${pkg}::token::TOKEN` });
  const tokenCoin = coins.data[0].coinObjectId;
  let i = 0;
  for (const u of [...users, ...withdrawers]) {
    await exec(i++ === 0 ? "pool::deposit_and_register (1st)" : `pool::deposit_and_register (${u.name})`, (tx) => {
      const [c] = tx.splitCoins(tx.object(tokenCoin), [tx.pure.u64(DENOM_SMALL)]);
      tx.moveCall({
        target: `${pkg}::pool::deposit_and_register`,
        arguments: [tx.object(pool), c, tx.pure.vector("u8", Array.from(le32(u.commitment))), tx.object("0x6")],
      });
    });
  }

  const auditorKey = new Uint8Array(33).fill(2);
  const cc = await exec("compliance::create_compliance_config", (tx) => tx.moveCall({
    target: `${pkg}::compliance::create_compliance_config`,
    arguments: [tx.object(cap), tx.object(pool), tx.pure.vector("u8", Array.from(complianceVk)),
      tx.pure.vector("u8", Array.from(le32(credTree.root))), tx.pure.u64(1), tx.pure.vector("u8", Array.from(auditorKey))],
  }));
  const config = created(cc, "::compliance::ComplianceConfig");

  await exec("pool::update_commitment_root", (tx) => tx.moveCall({
    target: `${pkg}::pool::update_commitment_root`,
    arguments: [tx.object(pool), tx.object(cap), tx.pure.vector("u8", Array.from(le32(tree.root))), tx.object("0x6")],
  }));
  const e0 = Math.floor((await chainMs()) / EPOCH_MS);
  console.log(`  waiting for pool epoch ${e0 + 1} (root + withdraw VK timelock, deposit maturity)...`);
  let epoch = await waitForEpoch(e0 + 1);

  // --- transfer proofs ---
  const transferInput = (u, ep) => {
    const txAmount = 100n, salt = 7n + u.secret;
    return {
      oldCommitment: u.commitment,
      newCommitment: H([D.COMMIT, u.cumOld + txAmount, u.rNew, u.secret]),
      threshold: THRESHOLD, epochId: BigInt(ep),
      nullifier: H([D.NULL, u.secret, BigInt(ep), u.rOld]),
      txAmountHash: H([D.TXAMT, txAmount, salt]),
      merkleRoot: tree.root,
      cumulativeOld: u.cumOld, cumulativeNew: u.cumOld + txAmount, txAmount,
      randomnessOld: u.rOld, randomnessNew: u.rNew, userSecret: u.secret, salt,
      ...tree.path(users.indexOf(u)),
    };
  };
  const callTransfer = (name, p, opts) => exec(name, (tx) => tx.moveCall({
    target: `${pkg}::pool::shielded_transfer`,
    arguments: [tx.object(pool), tx.pure.vector("u8", Array.from(p.proof)), tx.pure.vector("u8", Array.from(p.inputs)), tx.object("0x6")],
  }), opts);

  for (const [n, label] of [["T1", "pool::shielded_transfer (1st)"], ["T2", "pool::shielded_transfer (2nd)"]]) {
    const p = await prove("transfer", "build", transferInput(users.find((u) => u.name === n), epoch));
    await callTransfer(label, p);
  }

  // --- withdrawals ---
  const recipientA = BigInt(me) % 21888242871839275222246405745257275088548364400416034343698204186575808495617n;
  const withdrawInput = (w, recipient) => ({
    commitment: w.commitment, withdrawAmount: w.amount,
    nullifier: H([D.WNULL, w.secret, w.rOld, w.cumOld]),
    recipientHash: H([D.RECIP, recipient]),
    newCommitment: H([D.COMMIT, w.cumOld - w.amount, w.rNew, w.secret]),
    cumulativeOld: w.cumOld, randomnessOld: w.rOld, userSecret: w.secret, recipient, randomnessNew: w.rNew,
  });
  const callWithdraw = (name, p, recipientAddr, opts) => exec(name, (tx) => tx.moveCall({
    target: `${pkg}::pool::zk_withdraw`,
    arguments: [tx.object(pool), tx.pure.vector("u8", Array.from(p.proof)), tx.pure.vector("u8", Array.from(p.inputs)),
      tx.pure.address(recipientAddr), tx.object("0x6")],
  }), opts);
  {
    const p = await prove("withdraw", "build-withdraw", withdrawInput(withdrawers[0], recipientA));
    await callWithdraw("pool::zk_withdraw (1st)", p, me);
  }
  // W2's proof is bound to recipientA (= our address); E7 probe below submits it to another address.
  const w2proof = await prove("withdraw", "build-withdraw", withdrawInput(withdrawers[1], recipientA));

  // --- compliant transfers ---
  for (const [n, label] of [["C1", "compliance::compliant_transfer (1st)"], ["C2", "compliance::compliant_transfer (2nd)"]]) {
    const u = users.find((x) => x.name === n);
    const ti = transferInput(u, epoch);
    const tp = await prove("transfer", "build", ti);
    const ci = credLeaves.indexOf(H([D.CREDLEAF, u.secret, u.kyc, u.expiry, u.issuer]));
    const contextId = H([D.CTX, ti.nullifier, u.secret]);
    const cin = {
      merkleRoot: credTree.root, currentEpoch: BigInt(epoch), contextId, requiredKycLevel: 1n,
      nullifier: H([D.CNULL, u.secret, contextId]), validCredential: 1n,
      userSecret: u.secret, kycLevel: u.kyc, expiryEpoch: u.expiry, issuerId: u.issuer,
      ...credTree.path(ci), transferNullifier: ti.nullifier,
    };
    const cpf = await prove("compliance", "build-compliance", cin);
    await exec(label, (tx) => tx.moveCall({
      target: `${pkg}::compliance::compliant_transfer`,
      arguments: [tx.object(pool), tx.object(config),
        tx.pure.vector("u8", Array.from(tp.proof)), tx.pure.vector("u8", Array.from(tp.inputs)),
        tx.pure.vector("u8", Array.from(cpf.proof)), tx.pure.vector("u8", Array.from(cpf.inputs)),
        tx.pure.vector("u8", Array.from(randomBytes(128))), tx.object("0x6")],
    }));
  }

  // --- VK rotation: a proof under the OLD VK must be rejected afterwards (stale-cache probe) ---
  await exec("pool::propose_vk_update", (tx) => tx.moveCall({
    target: `${pkg}::pool::propose_vk_update`,
    arguments: [tx.object(pool), tx.object(cap), tx.pure.vector("u8", Array.from(transferVkAlt)), tx.object("0x6")],
  }));
  const e1 = Math.floor((await chainMs()) / EPOCH_MS);
  console.log(`  waiting for pool epoch ${e1 + 1} (VK rotation timelock)...`);
  epoch = await waitForEpoch(e1 + 1);
  {
    const stale = await prove("transfer", "build", transferInput(users.find((u) => u.name === "T3"), epoch));
    await callTransfer("NEG stale-VK proof after rotation", stale, { expectAbort: 3, record: true });
    const fresh = await prove("transfer", "build", transferInput(users.find((u) => u.name === "T4"), epoch), "transfer_alt_final.zkey");
    await callTransfer("pool::shielded_transfer (post-rotation)", fresh);
  }

  await exec("pool::freeze_pool", (tx) => tx.moveCall({ target: `${pkg}::pool::freeze_pool`, arguments: [tx.object(pool), tx.object(cap), tx.object("0x6")] }));
  await exec("pool::unfreeze_pool", (tx) => tx.moveCall({ target: `${pkg}::pool::unfreeze_pool`, arguments: [tx.object(pool), tx.object(cap)] }));

  // --- E7 probe: proof bound to recipientA, submitted with a different recipient address ---
  const other = Ed25519Keypair.generate().toSuiAddress();
  let e7 = "NOT RUN";
  const tx7 = new Transaction();
  tx7.setGasBudget(GAS_BUDGET);
  tx7.moveCall({
    target: `${pkg}::pool::zk_withdraw`,
    arguments: [tx7.object(pool), tx7.pure.vector("u8", Array.from(w2proof.proof)), tx7.pure.vector("u8", Array.from(w2proof.inputs)),
      tx7.pure.address(other), tx7.object("0x6")],
  });
  const r7 = await client.signAndExecuteTransaction({ transaction: tx7, signer: kp, options: { showEffects: true, showBalanceChanges: true } });
  await client.waitForTransaction({ digest: r7.digest });
  const got = (r7.balanceChanges ?? []).find((b) => b.owner?.AddressOwner === other && b.coinType.endsWith("::token::TOKEN"));
  e7 = r7.effects.status.status === "success"
    ? `REDIRECTED: proof bound to ${me} paid ${got?.amount ?? "?"} TOKEN units to unrelated address ${other} (digest ${r7.digest})`
    : `rejected: ${r7.effects.status.error}`;
  console.log(`[${LABEL}] E7 recipient-binding probe: ${e7}`);

  console.log(`\n=== Summary (${LABEL}) — gas in MIST at RGP ${RGP}; computationUnits = computationCost / RGP ===`);
  console.table(rows.map((r) => ({ op: r.op, status: r.status, compMist: r.computationCost, units: r.computationUnits, storage: r.storageCost, rebate: r.storageRebate, net: r.netMist })));
  if (JSON_OUT) writeFileSync(JSON_OUT, JSON.stringify({ label: LABEL, rgp: Number(RGP), rows, e7 }, null, 2));
  rmSync(work, { recursive: true, force: true });
}

main().then(() => process.exit(0)).catch((e) => { console.error("[FATAL]", e); process.exit(1); });
